package com.smartdairy.service; import com.smartdairy.entity.Distributor; import com.smartdairy.repository.DistributorRepository; import java.sql.SQLException; import java.util.List;
public class DistributorService{private final DistributorRepository repo=new DistributorRepository(); public void save(Distributor d)throws Exception{require(d.getName(),"Name");repo.save(d);} public void update(Distributor d)throws Exception{if(d.getId()<=0)throw new IllegalArgumentException("Invalid distributor id");saveUpdate(d);} private void saveUpdate(Distributor d)throws Exception{require(d.getName(),"Name");repo.update(d);} public void delete(int id)throws Exception{repo.delete(id);} public List<Distributor> findAll()throws Exception{return repo.findAll();} private void require(String s,String n){if(s==null||s.trim().isEmpty())throw new IllegalArgumentException(n+" is required");}}
